function go(id){sfx('click');document.querySelectorAll('.sec').forEach(s=>s.classList.remove('active'));document.querySelectorAll('.nav-t[role="tab"]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-selected','false');});document.getElementById(id).classList.add('active');const btn=document.querySelector(`[data-s="${id}"]`);if(btn){btn.classList.add('active');btn.setAttribute('aria-selected','true');}window.scrollTo({top:0,behavior:'smooth'});if(id==='s-sopa'){setTimeout(buildSopa,50);}if(id==='s-widgets'){setTimeout(buildRoute,50);}}

// ===================== FLASHCARD DATA =====================
const fcData=[{"w":"Activo","a":"💰 Todo lo que <strong>mete dinero</strong> a tu bolsillo, o lo ahorra, aunque tú no estés trabajando: un cuarto alquilado, una herramienta que te da trabajos, un terreno sembrado, un curso que ya está grabado y se sigue vendiendo."},{"w":"Pasivo","a":"🕳️ Todo lo que <strong>saca dinero</strong> de tu bolsillo mes a mes, lo uses o no: la cuota de un préstamo de consumo, el seguro y el mantenimiento de un carro de paseo, una suscripción olvidada."},{"w":"La pregunta que decide","a":"❓ No es «¿cuánto costó?» sino <strong>«¿en qué dirección mueve el dinero cada mes?»</strong>. Lo mismo puede ser activo o pasivo según el uso: una motocicleta que reparte pedidos es activo; la misma motocicleta solo para pasear es pasivo."},{"w":"Ingreso","a":"📥 El dinero que <strong>entra</strong> en un período: salario, ventas, alquileres, intereses. Un ingreso alto no significa riqueza si sale igual de rápido."},{"w":"Egreso o gasto","a":"📤 El dinero que <strong>sale</strong>: comida, transporte, cuotas, servicios. Hay gastos que sostienen la vida y gastos que solo alimentan pasivos."},{"w":"Flujo de caja","a":"🌊 Ingresos menos egresos en un período. Es lo que <strong>de verdad manda</strong>: se puede tener bienes y estar ahogado si el flujo es negativo."},{"w":"Patrimonio","a":"🏛️ Lo que <strong>queda</strong> si vendes todo y pagas todo lo que debes: activos menos deudas. Es la foto de la riqueza; el flujo es la película."},{"w":"Ingreso activo","a":"🏃 El que <strong>depende de tus horas</strong>: si no trabajas, no entra. El salario y el trabajo por encargo son ingreso activo."},{"w":"Ingreso pasivo","a":"🌱 El que <strong>sigue entrando</strong> aunque estés durmiendo: alquiler, intereses, regalías, un producto que ya está hecho y se vende solo."},{"w":"Depreciación","a":"📉 Lo que un bien <strong>pierde de valor</strong> con el tiempo. Un teléfono o un carro valen menos cada año: por eso comprarlos a crédito duele dos veces."},{"w":"Interés compuesto","a":"🔁 El interés que gana interés. Trabaja <strong>a tu favor</strong> cuando ahorras o inviertes, y <strong>en tu contra</strong> cuando debes: por eso una deuda pequeña que no se paga se vuelve grande sola."},{"w":"Fondo de emergencia","a":"🛟 Dinero guardado y disponible que cubre de <strong>tres a seis meses</strong> de gastos. No es una inversión: es lo que evita que un imprevisto te obligue a endeudarte con interés alto."},{"w":"Deuda buena y deuda mala","a":"⚖️ La <strong>buena</strong> compra algo que produce más de lo que cuesta el interés (una herramienta de trabajo). La <strong>mala</strong> paga consumo que se acaba antes que la deuda."},{"w":"Costo de oportunidad","a":"🔀 Lo que <strong>dejas de ganar</strong> por usar el dinero en una cosa y no en otra. Comprar un pasivo no solo cuesta su precio: cuesta el activo que no compraste."},{"w":"Liquidez","a":"💧 Qué tan rápido puedes convertir un bien en dinero <strong>sin regalarlo</strong>. Un terreno puede valer mucho y no servir para una emergencia el martes."},{"w":"La trampa del «me lo merezco»","a":"🎭 El gasto que se justifica con emoción y se paga con años de cuotas. La pregunta honesta no es si te lo mereces: es <strong>qué te va a costar cada mes</strong> y qué dejas de construir mientras lo pagas."}];
let fcIdx=0;
function upFC(){document.getElementById('fcInner').classList.remove('flipped');document.getElementById('fcW').textContent=fcData[fcIdx].w;document.getElementById('fcA').innerHTML=fcData[fcIdx].a;document.getElementById('fcCtr').textContent=(fcIdx+1)+' / '+fcData.length;}
function flipCard(){sfx('flip');document.getElementById('fcInner').classList.toggle('flipped');if(!xpTracker.fc.has(fcIdx)){xpTracker.fc.add(fcIdx);pts(1);}if(xpTracker.fc.size===fcData.length){fin('s-flash');unlockAchievement('flash_master');}}
function nextFC(){sfx('click');fcIdx=(fcIdx+1)%fcData.length;upFC();}
function prevFC(){sfx('click');fcIdx=(fcIdx-1+fcData.length)%fcData.length;upFC();}

// ===================== QUIZ DATA =====================
const qzData=[{"q":"¿Cuál es la prueba para saber si algo es activo o pasivo?","o":["a) Cuánto costó","b) En qué dirección mueve el dinero cada mes","c) Si es nuevo o usado","d) Si se puede vender rápido"],"c":1},{"q":"Una motocicleta que usas para repartir pedidos pagados es…","o":["a) Siempre un pasivo, porque gasta combustible","b) Un activo, porque produce más de lo que cuesta mantenerla","c) Ni activo ni pasivo","d) Un activo solo si está nueva"],"c":1},{"q":"¿Qué es el patrimonio de una familia?","o":["a) Todo lo que gana en un año","b) Sus activos menos todo lo que debe","c) El dinero que tiene en efectivo","d) El valor de su casa"],"c":1},{"q":"Se puede tener buen salario y estar ahogado. ¿Por qué?","o":["a) Porque el salario no cuenta como ingreso","b) Porque el flujo de caja es negativo: sale más de lo que entra","c) Porque no tiene tarjeta de crédito","d) Eso no puede pasar"],"c":1},{"q":"¿Cuál de estos es ingreso pasivo?","o":["a) Horas extra en la escuela","b) El alquiler de un cuarto que ya está construido","c) Un trabajo por encargo","d) Vender el teléfono viejo"],"c":1},{"q":"El interés compuesto en una deuda que no se paga…","o":["a) Se mantiene igual","b) Crece solo, porque el interés genera más interés","c) Se perdona a los seis meses","d) Solo aplica a los bancos"],"c":1},{"q":"¿Para qué sirve el fondo de emergencia?","o":["a) Para invertir en lo que dé más rendimiento","b) Para no tener que endeudarse con interés alto ante un imprevisto","c) Para comprar a crédito con más confianza","d) Para pagar las vacaciones"],"c":1},{"q":"«Compre este carro, es una inversión.» ¿Qué falla en esa frase?","o":["a) Nada, un carro siempre sube de valor","b) Un carro de uso personal se deprecia y saca dinero cada mes: es un pasivo","c) Que no dijo el precio","d) Que los carros no se pueden vender"],"c":1},{"q":"¿Qué es el costo de oportunidad de comprar un pasivo caro?","o":["a) El impuesto que se paga","b) El activo que se dejó de comprar con ese mismo dinero","c) El tiempo de ir a la tienda","d) La garantía perdida"],"c":1},{"q":"Dos familias ganan lo mismo. Una se hace más rica cada año. ¿Qué la diferencia?","o":["a) La suerte","b) Que convierte parte de su flujo en activos en vez de en pasivos","c) Que gasta menos en comida","d) Que tiene más tarjetas"],"c":1}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
function showQz(){if(qzIdx>=qzData.length){document.getElementById('qzQ').textContent='🎉 ¡Quiz completado!';document.getElementById('qzOpts').innerHTML='';fin('s-quiz');unlockAchievement('primer_quiz');return;}const q=qzData[qzIdx];document.getElementById('qzProg').textContent=`Pregunta ${qzIdx+1} de ${qzData.length}`;document.getElementById('qzQ').textContent=q.q;const opts=document.getElementById('qzOpts');opts.innerHTML='';q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(qzDone)return;document.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');qzSel=i;sfx('click');};opts.appendChild(b);});qzDone=false;}
function checkQz(){if(qzSel<0)return fb('fbQz','Selecciona una respuesta.',false);qzDone=true;const opts=document.querySelectorAll('.qz-opt');if(qzSel===qzData[qzIdx].c){opts[qzSel].classList.add('correct');fb('fbQz','¡Correcto! +5 XP',true);if(!xpTracker.qz.has(qzIdx)){xpTracker.qz.add(qzIdx);pts(5);}sfx('ok');}else{opts[qzSel].classList.add('wrong');opts[qzData[qzIdx].c].classList.add('correct');fb('fbQz','Incorrecto. Revisa la respuesta correcta.',false);sfx('no');}setTimeout(()=>{qzIdx++;qzSel=-1;showQz();},1600);}
function resetQz(){sfx('click');qzIdx=0;qzSel=-1;qzDone=false;showQz();document.getElementById('fbQz').classList.remove('show');}

