const identifyTaskDB=[{"s":"Un cuarto que se alquila cada mes y solo pide mantenimiento.","type":"Activo"},{"s":"Una cuota fija que sale del bolsillo aunque el bien esté guardado.","type":"Pasivo"},{"s":"Lo que entra menos lo que sale en un mes completo.","type":"Flujo de caja"},{"s":"Lo que queda después de vender todo y pagar todas las deudas.","type":"Patrimonio"},{"s":"El dinero guardado que cubre tres meses de gastos sin tocar deuda.","type":"Fondo de emergencia"},{"s":"El interés que se calcula sobre el interés acumulado.","type":"Interés compuesto"},{"s":"Lo que un bien pierde de valor con el paso del tiempo.","type":"Depreciación"},{"s":"El activo que se dejó de comprar por gastar en otra cosa.","type":"Costo de oportunidad"}];
