function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un vendedor insiste: \"Llévelo hoy, la cuota es de apenas L 750 al mes, ni la va a sentir\"."},{"txt":"Un conocido asegura: \"Métale a este negocio, paga 20% mensual garantizado, yo ya cobré dos veces; pero tiene que entrar esta semana\"."},{"txt":"Un agente le dice: \"Un carro nuevo es una inversión, y además le da estatus para conseguir mejores contratos\"."},{"txt":"Un familiar propone: \"Saque un préstamo para pagar los otros préstamos, así queda con una sola cuota más baja\"."}];
const critCaseQuestions=["1. ¿Qué parte de lo que dicen es cierto y qué parte es un truco de venta?","2. ¿Qué número exacto hay que pedir o calcular antes de decidir?","3. Escribe tu respuesta de 3-4 frases, tal como se la dirías de frente.","4. ¿En qué caso concreto SÍ convendría aceptar, y con qué condición?"];
const critCaseGuides=["Casi siempre el hecho suelto es cierto (la cuota es esa, el carro sirve, el negocio pagó a alguien): el truco está en lo que se omite, que es el costo total, el riesgo y qué pasa si algo falla.","Pide o calcula: precio de contado contra cuota por plazo, tasa de interés real, comisiones, qué pasa si te atrasas, y en negocios, de dónde sale el rendimiento y quién responde por escrito.","Respuesta modelo: reconocer lo cierto, poner el número completo sobre la mesa y decidir con él, sin discutir la emoción. Cerrar con una condición concreta o con un no claro; la prisa que impone el otro no es tu prisa.","Casi siempre hay una versión aceptable: el crédito conviene si el bien produce más que su interés; consolidar deudas sirve solo si baja la tasa y no se abre crédito nuevo; un vehículo se justifica si genera ingreso o ahorra un costo mayor."];

const critErrorBank=[{"txt":"\"Como la cuota es baja, la compra es barata\".","g1":"El costo real es cuota por plazo, más comisiones: una cuota baja con plazo largo suele salir mucho más cara.","g2":"Y si el bien se deprecia, se termina pagando de más por algo que ya vale menos."},{"txt":"\"Todo lo que se compra con esfuerzo es una inversión\".","g1":"Inversión es lo que produce un retorno; si el bien solo genera cuotas y mantenimiento, es un pasivo por más esfuerzo que costara.","g2":"La prueba sigue siendo la misma: hacia dónde mueve el dinero cada mes."},{"txt":"\"Si tengo bienes, no necesito fondo de emergencia\".","g1":"Los bienes suelen ser poco líquidos: venderlos con prisa significa venderlos mal.","g2":"El fondo existe justo para no tener que rematar un activo ni endeudarse caro el día del imprevisto."},{"txt":"\"Un rendimiento alto garantizado existe si uno conoce a la persona correcta\".","g1":"Rendimiento y riesgo van juntos: la garantía de un rendimiento altísimo es la señal más clara de fraude.","g2":"Los esquemas piramidales pagan a los primeros con el dinero de los siguientes y se caen cuando dejan de entrar nuevos."}];

const critDecisionBank=["Una familia con deudas al 5% mensual recibe un dinero extra y duda entre pagar la deuda o guardarlo en un ahorro que paga 1% mensual.","Un maestro puede comprar de contado una computadora que necesita para trabajar, o financiarla a 24 cuotas y usar el efectivo para mercadería que rota cada mes.","Una pareja quiere comprar carro nuevo mientras alquila la casa donde vive y no tiene fondo de emergencia.","Un vecino ofrece vender un terreno barato, pero hay que decidir en 48 horas y sin escritura a la vista."];
const critDecisionGuide="La decisión correcta sigue los principios de M.E.T.A.S: offline-first (el dispositivo primero, la nube como copia), costo ~$0 (Pages + Supabase Free), cero dependencias frágiles (JS puro, sin compilación), un solo código para web/PWA/APK (Capacitor) y minimización de datos de menores (códigos y claves en vez de nombres). Cada alternativa contraria agrega costo, fragilidad o riesgo sin necesidad.";

const critCompareBank=[{"a":"Comprar una máquina de L 8,000 con préstamo, que deja L 2,500 al mes.","b":"Comprar un televisor de L 12,000 a 24 cuotas de L 750.","ga":"Caso A: el activo paga su propia cuota y deja excedente desde el primer mes; el riesgo es que baje la demanda del servicio.","gb":"Caso B: L 18,000 pagados por un bien que se deprecia y no produce nada; el costo del crédito sale del trabajo futuro.","gr":"No es que una compra sea moral y la otra no: es que una se paga sola y la otra la pagas tú."},{"a":"Guardar tres meses de gastos disponibles antes de invertir.","b":"Invertir todo el sobrante de inmediato para no perder rendimiento.","ga":"Caso A: rinde menos, pero sostiene el plan cuando llega el imprevisto que siempre llega.","gb":"Caso B: rinde más en el papel, y obliga a vender a mal precio o a endeudarse caro el primer mes malo.","gr":"El orden importa: primero la protección, después el rendimiento."}];

const critCauseBank=[{"cause":"Cada aumento de ingreso se acompaña de una compra nueva a cuotas.","guide":"Inflación de estilo de vida: el ingreso sube y el sobrante no, porque los pasivos crecieron al mismo ritmo. El patrimonio se queda igual mientras el trabajo aumenta."},{"cause":"Se paga solo el mínimo de una deuda con interés alto.","guide":"El pago apenas cubre el interés y el capital casi no baja: el interés compuesto trabaja en contra y la deuda se estira por años."},{"cause":"No existe fondo de emergencia y se descompone la moto de trabajo.","guide":"La reparación se financia con crédito caro o se vende un activo con prisa: un imprevisto se convierte en un retroceso de meses."},{"cause":"Se compra un bien que se deprecia usando deuda a plazo largo.","guide":"Se paga interés sobre algo que pierde valor: al terminar las cuotas, el bien vale una fracción de lo pagado."}];
const critEffectBank=[{"effect":"Al año siguiente la familia debe menos y tiene los mismos ingresos, pero le sobra dinero cada mes.","guide":"Bajaron los pasivos: cada cuota apagada liberó flujo, y ese flujo ya no se comprometió otra vez."},{"effect":"Una emergencia médica se pagó sin pedir prestado ni vender nada.","guide":"El fondo de emergencia hizo su trabajo: convirtió una crisis en un gasto planificado."},{"effect":"La máquina de trabajo se pagó sola en cuatro meses y sigue produciendo.","guide":"Era deuda que construye: el activo generaba más que el costo del crédito, así que el préstamo compró ingreso, no consumo."},{"effect":"Varias familias del barrio perdieron su dinero en el mismo negocio de rendimientos altos.","guide":"Esquema piramidal: pagaba a los primeros con el aporte de los nuevos y colapsó al frenarse la entrada de gente."}];

function genEvalCrit(){
  sfx('click');
  const cf=evalCritFormNum;window._currentEvalCritForm=cf;evalCritFormNum=(evalCritFormNum%10)+1;saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Pensamiento Crítico · Forma ${cf} · Activos y Pasivos · Ruta del Poder`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_pick(critCaseBank,1)[0];
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Caso de análisis: la interpelación del ingeniero <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_pick(critErrorBank,1)[0];
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_pick(critDecisionBank,1)[0];
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones: arquitectura <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué le recomendarías hacer según los principios de arquitectura de M.E.T.A.S, y por qué sería mejor que el plan descrito?</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_pick(critCompareBank,1)[0];
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cómo calificarías cada caso según los conceptos del panorama técnico? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pick(critCauseBank,2),effects=_pick(critEffectBank,3);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Pensamiento crítico: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Caso de análisis: la interpelación del ingeniero</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones: arquitectura</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué le recomendarías hacer según los principios de arquitectura de M.E.T.A.S, y por qué sería mejor que el plan descrito?</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cómo calificarías cada caso según los conceptos del panorama técnico? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Pensamiento Crítico Activos y Pasivos · Ruta del Poder · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{position:fixed;bottom:5mm;right:6mm;font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Pensamiento Crítico · Activos y Pasivos · Ruta del Poder · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Pensamiento Crítico · Activos y Pasivos · Ruta del Poder · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="forma-tag">Forma ${forma}</div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"👀","label":"Ver el flujo","text":"Anotar durante un mes <strong>todo</strong> lo que entra y lo que sale. Sin este paso se decide a ciegas: casi nadie acierta de memoria en qué se le va el dinero."},{"y":"2","icon":"🧾","label":"Separar activos de pasivos","text":"Listar los bienes de la familia y preguntarle a cada uno: <strong>¿me mete o me saca dinero cada mes?</strong> La respuesta ordena la lista en dos columnas honestas."},{"y":"3","icon":"🛟","label":"Levantar el fondo","text":"Apartar de tres a seis meses de gastos, disponibles. Es lo que corta el círculo de endeudarse caro cada vez que aparece un imprevisto."},{"y":"4","icon":"🔥","label":"Apagar la deuda cara","text":"Ordenar las deudas por interés y atacar la más cara mientras se paga el mínimo en las demás. Cada cuota liberada se suma a la siguiente."},{"y":"5","icon":"🌱","label":"Comprar el primer activo","text":"Con el flujo ya positivo, convertir parte del sobrante en algo que produzca: una herramienta, mercadería, un cuarto, un material que se venda dos veces."},{"y":"6","icon":"🏛️","label":"Repetir y proteger","text":"Reinvertir lo que produce el activo, no subir el estilo de vida al mismo ritmo, y dejar por escrito quién sabe qué: el patrimonio también se pierde por desorden."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').classList.add('show');sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🌱</span><span class="ms-text"><strong>Empieza a producir:</strong> el activo genera un ingreso propio cada mes, sin pedirte más horas.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🏛️</span><span class="ms-text"><strong>El patrimonio sube:</strong> ese ingreso compra el siguiente activo y el flujo crece solo. Así se construye, sin lotería.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🕳️</span><span class="ms-text"><strong>Aparece una cuota:</strong> el bien entra a la casa y con él una salida fija de dinero, la uses o no.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📉</span><span class="ms-text"><strong>El flujo se aprieta:</strong> mientras pagas, el bien pierde valor. No es pecado tenerlo: es peligroso no haberlo contado.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"activo":{"nombre":"El activo","icon":"💰","estructura":{"title":"Qué es","info":"• Todo lo que <strong>mete dinero</strong> o lo ahorra sin consumir tus horas<br>• Ejemplos de aquí: un cuarto alquilado, una máquina de trabajo, mercadería que rota, un terreno produciendo<br>• También cuenta lo que <strong>evita un gasto</strong> recurrente (una herramienta que reemplaza un alquiler)"},"funcion":{"title":"Cómo funciona","info":"• Produce un ingreso periódico, y ese ingreso puede comprar otro activo<br>• Se mide por lo que deja <strong>después</strong> de sus costos: renta menos mantenimiento e impuestos<br>• Un activo mal elegido puede volverse pasivo: un cuarto vacío solo cobra impuestos"},"enfermedades":{"title":"Riesgos y límites","info":"• Falta de <strong>liquidez</strong>: valen mucho y no sirven para una emergencia el martes<br>• Concentrar todo en uno solo: si falla, falla todo<br>• Confundir «caro» con «productivo»: el precio no dice la dirección del flujo"},"cuidados":{"title":"Ejemplo real","info":"• Una máquina de coser de L 8,000 que deja L 2,500 al mes se paga en poco más de tres meses y sigue produciendo<br>• Un cuarto alquilado en L 2,000 al mes, con L 300 de mantenimiento, deja L 1,700 limpios sin quitarte horas"}},"pasivo":{"nombre":"El pasivo","icon":"🕳️","estructura":{"title":"Qué es","info":"• Todo lo que <strong>saca dinero</strong> mes a mes, lo uses o no<br>• Cuotas de consumo, seguros y mantenimiento de bienes de uso personal, suscripciones dormidas<br>• No es pecado tener pasivos: es peligroso <strong>no saber cuáles son</strong>"},"funcion":{"title":"Cómo funciona","info":"• Compromete <strong>ingreso futuro</strong>: cada cuota es trabajo tuyo ya vendido<br>• Suele venir acompañado de depreciación: pagas más por algo que vale menos cada mes<br>• Se disfraza con la palabra «inversión» cuando no produce nada"},"enfermedades":{"title":"Riesgos y límites","info":"• La cuota baja esconde el <strong>costo total</strong>: hay que multiplicar cuota por plazo<br>• Los pasivos crecen con el ingreso si no se decide lo contrario<br>• Un pasivo financiado con deuda cara duele dos veces"},"cuidados":{"title":"Ejemplo real","info":"• Un televisor de L 12,000 a 24 cuotas de L 750 termina costando L 18,000: son L 6,000 que no compraron nada<br>• Una moto de paseo suma cuota, combustible, seguro y mantenimiento: cuatro salidas por una sola compra"}},"flujo":{"nombre":"El flujo de caja","icon":"🌊","estructura":{"title":"Qué es","info":"• Lo que <strong>entra</strong> menos lo que <strong>sale</strong> en un período<br>• Es la película del dinero; el patrimonio es solo la foto<br>• Positivo: sobra y se puede construir. Negativo: se vive del crédito"},"funcion":{"title":"Cómo funciona","info":"• Se mide anotando todo un mes completo, sin adornar<br>• Mejora por dos vías: subir ingresos o bajar salidas, y la segunda es más rápida<br>• En F.A.R.O lo llevan <strong>Finanzas Familia</strong> y <strong>Finanzas Escuela</strong>: ahí se ve el mes real, no el recordado"},"enfermedades":{"title":"Riesgos y límites","info":"• Un flujo positivo con ingresos de una sola fuente es frágil<br>• Los gastos anuales (matrícula, impuestos) hunden meses enteros si no se prorratean<br>• Anotar y no revisar no sirve de nada"},"cuidados":{"title":"Ejemplo real","info":"• Dos familias con el mismo ingreso: una con flujo de L 3,000 positivos construye; la otra con L 500 negativos se endeuda cada mes sin sentirlo"}},"patrimonio":{"nombre":"El patrimonio","icon":"🏛️","estructura":{"title":"Qué es","info":"• <strong>Activos menos deudas</strong>: lo que quedaría si vendieras todo y pagaras todo<br>• Puede ser negativo aunque haya bienes vistosos<br>• Es la medida honesta del avance de un año a otro"},"funcion":{"title":"Cómo funciona","info":"• Sube por tres caminos: pagar deuda, comprar activos o que los activos suban de valor<br>• Se calcula una vez al año con una hoja simple: lista de bienes, lista de deudas, resta<br>• El <strong>Inventario</strong> de F.A.R.O sirve de base para la primera columna"},"enfermedades":{"title":"Riesgos y límites","info":"• Inflar el valor de los bienes al calcularlo es engañarse solo<br>• Patrimonio alto con flujo negativo obliga a vender a mal precio<br>• Sin documentos ni acuerdos claros, el patrimonio familiar se pierde en desorden"},"cuidados":{"title":"Ejemplo real","info":"• Familia con terreno de L 300,000, herramientas por L 20,000 y deudas por L 90,000: patrimonio de L 230,000, aunque ese mes ande corta de efectivo"}}};
let labParte='activo',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente arquitecto en formación!','¡Dominas el panorama de M.E.T.A.S!','¡Maestro del Panorama Técnico!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏗️ ¡'+name+' completó el Módulo 1 de Autocapacitación M.E.T.A.S (Panorama técnico)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

